/**
 * The types `mechanics/cards/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CardDrawCandidate, CardDrawOdds
 * depends    src/data/cards/types
 * used by    src/mechanics/cards/draw-odds, src/mechanics/cards/index, src/save/cards/types
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { CardTemplate } from '../../data/cards/types'

// from draw-odds.ts

/** One card as a pull sees it: its rarity, and whether a pull can land on it now. */
export interface CardDrawCandidate {
  /** The card's id in `CARD_TEMPLATES`. */
  card: string
  rarity: CardTemplate['rarity']
  /** In the pool (not milestone-gated, or its milestone claimed) and below level 7. */
  drawable: boolean
}

export interface CardDrawOdds {
  /** Chance a pull lands in each rarity, 0 to 1. */
  rarities: Record<CardTemplate['rarity'], number>
  /** Chance a pull is each card, 0 to 1, in the order the candidates were given. */
  cards: { card: string, rarity: CardTemplate['rarity'], chance: number }[]
  /**
   * Each move of an emptied rarity's share that the game has not been seen to make. Empty when
   * every step is verified; only Common's share moving to Rare has been seen on screen.
   */
  unverified: string[]
}
